  [3801]={n="Dark Iron Legacy", l=52, r=48, g={"Franclorn Forgewright",1428,29.0,28.9}, t={"Franclorn Forgewright",1428,29.0,28.9}, ot="Speak with Franclorn Forgewright if you are interested in obtaining a key to the city major.", sh=true, nx=3802, xp={52,510}},
  [3802]={n="Dark Iron Legacy", l=52, r=48, g={"Franclorn Forgewright",1428,29.0,28.9}, t={"Monument of Franclorn Forgewright"}, ot="Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright.", sh=true, ps={3801}, xp={52,5100}},
  [3907]={n="Disharmony of Fire", l=56, r=48, g={"Thunderheart",1418,3.3,48.3}, t={"Thunderheart",1418,3.3,48.3}, ot="Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart.", sh=true, fa="H", ps={3906}, xp={56,7300}},
  [3981]={n="Commander Gor'shak", l=52, r=48, g={"Galamav the Marksman",1418,6.0,47.7}, t={"Commander Gor'shak"}, ot="Find Commander Gor'shak in Blackrock Depths.  You recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort.", sh=true, fa="H", ps={3906}, nx=3982, xp={52,5100}},
  [3982]={n="What Is Going On?", l=54, r=48, g={"Commander Gor'shak"}, t={"Commander Gor'shak"}, ot="Defend Gor'shak.", fa="H", ps={3981}, nx=4001, xp={54,4100}},
  [4001]={n="What Is Going On?", l=54, r=48, g={"Commander Gor'shak"}, t={"Thrall",1454,31.7,37.8}, ot="Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar.  You recall Gor'shak mentioning that Kharan is being held in a cell nearby.", sh=true, fa="H", ps={3981,3982}, nx=4002, xp={54,540}},
  [4002]={n="The Eastern Kingdom", l=54, r=48, g={"Thrall",1454,31.7,37.8}, t={"Thrall",1454,31.7,37.8}, ot="Speak with Thrall if you are prepared to take on the mission he has planned.", sh=true, fa="H", ps={4001}, nx=4003},
  [4003]={n="The Royal Rescue", l=59, r=48, g={"Thrall",1454,31.7,37.8}, t={"Princess Moira Bronzebeard"}, ot="Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell.", sh=true, fa="H", ps={4002}, nx=4004, xp={59,8050}},
  [4004]={n="The Princess Saved?", l=60, r=48, g={"Princess Moira Bronzebeard"}, t={"Thrall",1454,31.7,37.8}, ot="Return to Thrall!", sh=true, fa="H", ps={4003}, xp={60,9950}},
  [4024]={n="A Taste of Flame", l=58, r=52, g={"Cyrus Therepentous",1428,95.1,31.6}, t={"Cyrus Therepentous",1428,95.1,31.6}, ot="Travel to Blackrock Depths and slay Bael'Gar.  You only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.  Return the Encased Fiery Essence to Cyrus Therepentous.", ps={4022,4023}, xp={58,6200}},
  [4063]={n="The Rise of the Machines", l=58, r=52, g={"Lotwil Veriatus",1418,25.9,44.9}, t={"Lotwil Veriatus",1418,25.9,44.9}, ot="Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.", sh=true, fa="H", ps={4062}, xp={58,6200}},
  [4081]={n="KILL ON SIGHT: Dark Iron Dwarves", l=52, r=48, g={"WANTED",1418,3.7,47.4}, t={"Warlord Goretooth",1418,5.8,47.5}, ot="Venture to Blackrock Depths and destroy the vile aggressors!  Warlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.", sh=true, fa="H", nx=4082, xp={52,5100}},
  [4082]={n="KILL ON SIGHT: High Ranking Dark Iron Officials", l=54, r=50, g={"KILL ON SIGHT",1418,3.9,46.7}, t={"Warlord Goretooth",1418,5.8,47.5}, ot="Venture to Blackrock Depths and destroy the vile aggressors!  Warlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete.", sh=true, fa="H", ps={4081}, nx=4122, xp={54,5450}},
  [4083]={n="The Spectral Chalice", l=55, r=40, g={"Spectral Chalice"}, t={"Spectral Chalice"}, sh=true, xp={55,560}},
  [4121]={n="Precarious Predicament", l=58, r=52, g={"Grark Lorkrub",1428,40.2,34.2}, t={"Lexlort",1418,5.9,47.6}, ot="Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge.  You recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody.  You will also be required to hand over your Thorium Shackles to Lexlort.", fa="H", ps={4122}, nx=4132, xp={58,7750}},
  [4122]={n="Grark Lorkrub", l=58, r=52, g={"Lexlort",1418,5.9,47.6}, t={"Grark Lorkrub",1428,40.2,34.2}, ot="Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress.  When you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody.", fa="H", ps={4082}, nx=4121, xp={58,6200}},
  [4123]={n="The Heart of the Mountain", l=55, r=50, g={"Maxwort Uberglint",1428,65.2,23.9}, t={"Maxwort Uberglint",1428,65.2,23.9}, ot="Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes.", sh=true, xp={55,5650}},
