  [4241]={n="Marshal Windsor", l=54, r=48, g={"Marshal Maxwell",1428,84.7,69.0}, t={"Marshal Windsor"}, ot="Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor.  You recall Ragged John talking about Windsor being dragged off to a prison.", sh=true, fa="A", ps={4224}, nx=4242, xp={54,5450}},
  [4242]={n="Abandoned Hope", l=54, r=48, g={"Marshal Windsor"}, t={"Marshal Maxwell",1428,84.7,69.0}, ot="Give Marshal Maxwell the bad news.", sh=true, fa="A", ps={4241}, nx=4264, xp={54,5450}},
  [4263]={n="Incendius!", l=56, r=48, g={"Jalinda Sprig",1428,85.4,70.1}, t={"Jalinda Sprig",1428,85.4,70.1}, ot="Find Lord Incendius in Blackrock Depths and destroy him!", sh=true, fa="A", ps={4262}, xp={56,5800}},
  [4264]={n="A Crumpled Up Note", l=58, r=50, g={"(item) A Crumpled Up Note from Anvilrage Overseer, Anvilrage Warden, Anvilrage Guardsman"}, t={"Marshal Windsor"}, ot="You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all.", fa="A", ps={4242}, nx=4282, xp={58,6200}},
