  [4341]={n="Kharan Mighthammer", l=59, r=50, g={"King Magni Bronzebeard",1455,39.1,56.2}, t={"Kharan Mighthammer"}, ot="Travel to Blackrock Depths and find Kharan Mighthammer.  The King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison.", sh=true, fa="A", ps={3701}, nx=4342, xp={59,6400}},
  [4342]={n="Kharan's Tale", l=59, r=50, g={"Kharan Mighthammer"}, t={"Kharan Mighthammer"}, ot="Listen as Kharan Mighthammer tells his story.", sh=true, fa="A", ps={4341}, nx=4361, xp={59,1600}},
  [4361]={n="The Bearer of Bad News", l=59, r=50, g={"Kharan Mighthammer"}, t={"King Magni Bronzebeard",1455,39.1,56.2}, ot="Return to Ironforge and deliver the bad news to King Magni Bronzebeard.", sh=true, fa="A", ps={4342}, nx=4362, xp={59,6400}},
  [4362]={n="The Fate of the Kingdom", l=59, r=50, g={"King Magni Bronzebeard",1455,39.1,56.2}, t={"Princess Moira Bronzebeard"}, ot="Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan.", sh=true, fa="A", ps={4361}, nx=4363, xp={59,8050}},
