  [4701]={n="Put Her Down", l=59, r=55, g={"Helendis Riverhorn",1428,85.8,69.0}, t={"Helendis Riverhorn",1428,85.8,69.0}, ot="Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg.", sh=true, fa="A", xp={59,6400}},
  [4724]={n="The Pack Mistress", l=59, r=55, g={"Galamav the Marksman",1418,6.0,47.7}, t={"Galamav the Marksman",1418,6.0,47.7}, ot="Slay Halycon, pack mistress of the Bloodaxe worg.", sh=true, fa="H", xp={59,6400}},
