  [4734]={n="Egg Freezing", l=60, r=57, g={"Tinkee Steamboil",1428,65.2,24}, t={"Tinkee Steamboil",1428,65.2,24}, ot="Use the Eggscilloscope Prototype on an egg in the Rookery.", ps={4810}, nx=4735, xp={60,8300}},
  [4735]={n="Egg Collection", l=60, r=57, g={"Tinkee Steamboil",1428,65.2,24}, t={"Tinkee Steamboil",1428,65.2,24}, ot="Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes.", ps={4734}, nx=5522, xp={60,9950}},
  [4742]={n="Seal of Ascension", l=60, r=57, g={"Scarshield Infiltrator"}, t={"Scarshield Infiltrator"}, ot="Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.  The Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak of the Bloodaxe.", sh=true, nx=4743, xp={60,8300}},
  [4743]={n="Seal of Ascension", l=60, r=57, g={"Scarshield Infiltrator"}, t={"Scarshield Infiltrator"}, ot="Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.  It is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the ", ps={4742}, xp={60,9950}},
  [4764]={n="Doomrigger's Clasp", l=60, r=57, g={"Mayara Brightwing",1428,84.8,69.1}, t={"Mayara Brightwing",1428,84.8,69.1}, ot="Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes.", sh=true, fa="A", nx=4765, xp={60,1650}},
  [4765]={n="Delivery to Ridgewell", l=60, r=57, g={"Mayara Brightwing",1428,84.8,69.1}, t={"Count Remington Ridgewell",1453,76.9,47.8}, ot="Bring Ridgewell's Crate to Remington Ridgewell in Stormwind.", fa="A", ps={4764}, xp={60,6600}},
  [4766]={n="Mayara Brightwing", l=60, r=57, g={"Count Remington Ridgewell",1453,76.9,47.8}, t={"Mayara Brightwing",1428,84.8,69.1}, ot="Speak with Mayara Brightwing in the Burning Steppes.", sh=true, fa="A", nx=4764, xp={60,660}},
  [4768]={n="The Darkstone Tablet", l=60, r=57, g={"Shadowmage Vivian Lagrave",1418,2.9,47.8}, t={"Shadowmage Vivian Lagrave",1418,2.9,47.8}, ot="Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath.", sh=true, fa="H", xp={60,8300}},
  [4769]={n="Vivian Lagrave and the Darkstone Tablet", l=60, r=57, g={"Apothecary Zinge",1458,50.1,68.0}, t={"Shadowmage Vivian Lagrave",1418,2.9,47.8}, ot="Speak with Shadowmage Vivian Lagrave.", sh=true, fa="H", nx=4768, xp={60,660}},
  [4771]={n="Dawn's Gambit", l=60, r=57, g={"Betina Bigglezink",1423,71.7,49.9}, t={"Betina Bigglezink",1423,71.7,49.9}, ot="Place Dawn's Gambit in the Viewing Room of the Scholomance. Defeat Vectus, then return to Betina Bigglezink.", ps={5531}, xp={60,9950}},
  [4788]={n="The Final Tablets", l=58, r=40, g={"Prospector Ironboot",1446,66.9,24.0}, t={"Prospector Ironboot",1446,66.9,24.0}, ot="Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris.", sh=true, ps={5065}, nx=8181, xp={58,7750}},
  [4862]={n="En-Ay-Es-Tee-Why", l=59, r=55, g={"Kibler",1428,65.9,21.9}, t={"Kibler",1428,65.9,21.9}, ot="Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler.  By the sound of it, these eggs could be found near spiders.", sh=true, xp={59,6400}},
  [4866]={n="Mother's Milk", l=60, r=55, g={"Ragged John",1428,65.0,23.8}, t={"Ragged John",1428,65.0,23.8}, ot="In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you.", sh=true, xp={60,9950}},
  [4867]={n="Urok Doomhowl", l=60, r=55, g={"Warosh"}, t={"Warosh"}, ot="Read Warosh's Scroll. Bring Warosh's Mojo to Warosh.", xp={60,9950}},
  [4903]={n="Warlord's Command", l=60, r=55, g={"Warlord Goretooth",1418,5.8,47.5}, t={"Warlord Goretooth",1418,5.8,47.5}, ot="Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.", fa="H", nx=4941, xp={60,8300}},
