  [4982]={n="Bijou's Belongings", l=59, r=55, g={"Bijou"}, t={"Bijou"}, ot="Find Bijou's Belongings and return them to her. You recall her mentioning that she stashed them on the bottom floor of the city.", sh=true, fa="H", ps={4981}, nx=4983, xp={59,6400}},
