  [5102]={n="General Drakkisath's Demise", l=60, r=55, g={"Marshal Maxwell",1428,84.7,69.0}, t={"Marshal Maxwell",1428,84.7,69.0}, ot="Travel to Blackrock Spire and destroy General Drakkisath. Return to Marshal Maxwell when the job is done.", sh=true, fa="A", ps={5089}, xp={60,9950}},
  [5122]={n="The Medallion of Faith", l=60, r=55, g={"Aurius"}, t={"Aurius"}, sh=true, nx=5125},
  [5125]={n="Aurius' Reckoning", l=60, r=55, g={"Aurius"}, t={"Aurius"}, sh=true, ps={5122}, xp={60,8300}},
  [5127]={n="The Demon Forge", l=60, r=55, g={"Lorax",1452,63.8,73.8}, t={"Lorax",1452,63.8,73.8}, ot="Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.  You must also find the Unforged Rune Covered Breastplate.  Return both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring.", ps={5126}, xp={60,8300}},
  [5160]={n="The Matron Protectorate", l=60, r=57, g={"Awbee"}, t={"Haleh",1452,54.5,51.2}, ot="Travel to Winterspring and find Haleh. Give her Awbee's scale.", nx=5161, xp={60,6600}},
  [5166]={n="Breastplate of the Chromatic Flight", l=60, r=57, g={"Catalogue of the Wayward",1422,39.4,66.6}, t={"Jeziba",1422,39.4,66.8}, ot="To forge the Breastplate of the Chromatic Flight, you will be required to bring the following items to Jeziba the 'Sculptor':  1 Chromatic Carapace.  10 Brilliant Chromatic Scales.  10 Blood of Heroes.  10 Frayed Abomination Stitchings.", sh=true, ps={5164}, xp={60,9950}},
  [5167]={n="Legplates of the Chromatic Defier", l=60, r=57, g={"Catalogue of the Wayward",1422,39.4,66.6}, t={"Jeziba",1422,39.4,66.8}, ot="To forge the Legplates of the Chromatic Defier, you will be required to bring the following items to Jeziba the 'Sculptor':  1 Chromatic Carapace.  10 Brilliant Chromatic Scales.  10 Blood of Heroes.  5 Skin of Shadow.", sh=true, ps={5164}, xp={60,9950}},
  [5212]={n="The Flesh Does Not Lie", l=60, r=55, g={"Betina Bigglezink",1423,71.7,49.9}, t={"Betina Bigglezink",1423,71.7,49.9}, ot="Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample.", sh=true, nx=5213, xp={60,6600}},
  [5213]={n="The Active Agent", l=60, r=55, g={"Betina Bigglezink",1423,71.7,49.9}, t={"Betina Bigglezink",1423,71.7,49.9}, ot="Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink.", sh=true, ps={5212}, xp={60,6600}},
  [5214]={n="The Great Ezra Grimm", l=60, r=55, g={"Smokey LaRue",1423,70.9,48.4}, t={"Smokey LaRue",1423,70.9,48.4}, ot="Find Ezra Grimm's smoke shop in Stratholme and recover a box of Grimm's Premium Tobacco. Return to Smokey LaRue when the job is done.", sh=true, xp={60,8300}},
  [5243]={n="Houses of the Holy", l=60, r=55, g={"Leonid Barthalomew the Revered",1423,71.9,48.3}, t={"Leonid Barthalomew the Revered",1423,71.9,48.3}, ot="Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid.", sh=true, xp={60,6600}},
  [5251]={n="The Archivist", l=60, r=55, g={"Duke Nicholas Zverenhoff",1423,71.6,50.1}, t={"Duke Nicholas Zverenhoff",1423,71.6,50.1}, ot="Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.", sh=true, nx=5262, xp={60,8300}},
  [5262]={n="The Truth Comes Crashing Down", l=60, r=55, g={"(item) Head of Balnazzar from Grand Crusader Dathrohan"}, t={"Duke Nicholas Zverenhoff",1423,71.6,50.1}, ot="Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands.", ps={5251}, nx=5263, xp={60,8300}},
  [5263]={n="Above and Beyond", l=60, r=55, g={"Duke Nicholas Zverenhoff",1423,71.6,50.1}, t={"Duke Nicholas Zverenhoff",1423,71.6,50.1}, ot="Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff.", sh=true, ps={5262}, nx=5264, xp={60,8300}},
  [5282]={n="The Restless Souls", l=60, r=55, g={"Egan",1423,11.4,26.6}, t={"Egan",1423,11.4,26.6}, ot="Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs!  Free 15 Restless Souls and return to Egan.", ps={5281}, xp={60,8300}},
  [5305]={n="Sweet Serenity", l=60, r=50, g={"Lilith the Lithe",1452,61.3,37.1}, t={"Lilith the Lithe",1452,61.3,37.1}, ot="Travel to Stratholme and kill the Crimson Hammersmith. Recover the Crimson Hammersmith's Apron and return to Lilith.", sh=true, xp={60,8300}},
  [5306]={n="Snakestone of the Shadow Huntress", l=60, r=50, g={"Kilram",1452,61.3,37.1}, t={"Kilram",1452,61.3,37.1}, ot="Travel to Blackrock Spire and slay Shadow Hunter Vosh'gajin. Recover Vosh'gajin's Snakestone and return to Kilram.", sh=true, xp={60,8300}},
  [5307]={n="Corruption", l=60, r=50, g={"Seril Scourgebane",1452,61.3,37.2}, t={"Seril Scourgebane",1452,61.3,37.2}, ot="Find the Black Guard Swordsmith in Stratholme and destroy him. Recover the Insignia of the Black Guard and return to Seril Scourgebane.", sh=true, xp={60,8300}},
  [5341]={n="Barov Family Fortune", l=60, r=52, g={"Alexi Barov",1420,83.1,71.6}, t={"Alexi Barov",1420,83.1,71.6}, ot="Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task.", sh=true, fa="H", nx=5342, xp={60,6600}},
  [5343]={n="Barov Family Fortune", l=60, r=52, g={"Weldon Barov",1422,43.5,83.7}, t={"Weldon Barov",1422,43.5,83.7}, ot="Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task.", sh=true, fa="A", nx=5344, xp={60,6600}},
  [5382]={n="Doctor Theolen Krastinov, the Butcher", l=60, r=55, g={"Eva Sarkhoff",1422,70.2,73.7}, t={"Eva Sarkhoff",1422,70.2,73.7}, ot="Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete.", sh=true, nx=5515, xp={60,6600}},
  [5384]={n="Kirtonos the Herald", l=60, r=55, g={"Eva Sarkhoff",1422,70.2,73.7}, t={"Eva Sarkhoff",1422,70.2,73.7}, ot="Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.  Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff.", ps={5515}, nx=5461, xp={60,8300}},
  [5463]={n="Menethil's Gift", l=60, r=57, g={"Leonid Barthalomew the Revered",1423,71.9,48.3}, t={"Menethil's Gift"}, ot="Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground.", ps={5462}, nx=5464, xp={60,6600}},
  [5464]={n="Menethil's Gift", l=60, r=57, g={"Menethil's Gift"}, t={"Leonid Barthalomew the Revered",1423,71.9,48.3}, ot="Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands.", ps={5463}, nx=5465, xp={60,8300}},
  [5466]={n="The Lich, Ras Frostwhisper", l=60, r=57, g={"Magistrate Marduke",1422,70.6,74.1}, t={"Magistrate Marduke",1422,70.6,74.1}, ot="Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.", ps={5465}, xp={60,9950}},
  [5515]={n="Krastinov's Bag of Horrors", l=60, r=55, g={"Eva Sarkhoff",1422,70.2,73.7}, t={"Eva Sarkhoff",1422,70.2,73.7}, ot="Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.", sh=true, ps={5382}, nx=5384, xp={60,6600}},
  [5518]={n="The Gordok Ogre Suit", l=60, r=56, g={"Knot Thimblejack"}, t={"Knot Thimblejack"}, ot="Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack. He is currently chained inside the Gordok wing of Dire Maul.", sh=true, nx=5519, xp={60,6600}},
