  [7201]={n="The Last Element", l=54, r=48, g={"Shadowmage Vivian Lagrave",1418,2.9,47.8}, t={"Shadowmage Vivian Lagrave",1418,2.9,47.8}, ot="Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.", sh=true, fa="H", ps={3906}, xp={54,5450}},
  [7429]={n="Free Knot!", l=60, r=57, g={"Knot Thimblejack"}, t={"Knot Thimblejack"}, sh=true, ps={5525}},
  [7441]={n="Pusillin and the Elder Azj'Tordin", l=58, r=54, g={"Azj'Tordin",1444,76.9,37.4}, t={"Azj'Tordin",1444,76.9,37.4}, ot="Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.  Return to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.", sh=true, xp={58,7750}},
  [7461]={n="The Madness Within", l=60, r=56, g={"Shen'dralar Ancient"}, t={"Shen'dralar Ancient"}, ot="You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.  Enter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.  Return to the Shen'dralar Ancient in the courtyard should you complete t", sh=true, nx=7877, xp={60,9950}},
  [7463]={n="Arcane Refreshment", l=60, r=60, g={"Lorekeeper Lydros"}, t={"Lorekeeper Lydros"}, ot="Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence.", sh=true, cl=128, xp={60,6600}},
  [7481]={n="Elven Legends", l=60, r=54, g={"Sage Korolusk",1444,74.4,44}, t={"Sage Korolusk",1444,74.4,44}, ot="Search Dire Maul for Telmius Dreamseeker. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find.", sh=true, fa="H", xp={60,8300}},
  [7482]={n="Elven Legends", l=60, r=54, g={"Scholar Runethorn",1444,31.6,43.5}, t={"Scholar Runethorn",1444,31.6,43.5}, ot="Search Dire Maul for Telmius Dreamseeker. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find.", sh=true, fa="A", xp={60,8300}},
  [7483]={n="Libram of Rapidity", l=60, r=58, g={"Lorekeeper Lydros"}, t={"Lorekeeper Lydros"}, ot="Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity.", sh=true, ps={7481,7482}},
  [7484]={n="Libram of Focus", l=60, r=58, g={"Lorekeeper Lydros"}, t={"Lorekeeper Lydros"}, ot="Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus.", sh=true, ps={7481,7482}},
