  [7647]={n="Judgment and Redemption", l=60, r=60, g={"Lord Grayson Shadowbreaker",1453,48.4,50.2}, t={"Darkreaver's Fallen Charger"}, ot="Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth the spirits you must judge. Defeating these spirits will summon forth Death Knight Darkreaver. Defeat him and reclaim the lost soul of the fallen charger.  Give the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger.", fa="A", cl=2, ps={7646}, xp={60,9950}},
  [7703]={n="Unfinished Gordok Business", l=60, r=56, g={"Captain Kromcrush"}, t={"Captain Kromcrush"}, ot="Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.  According to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings.", xp={60,8300}},
  [7761]={n="Blackhand's Command", l=60, r=55, g={"(item) Blackhand's Command from Scarshield Quartermaster"}, t={"Drakkisath's Brand"}, ot="That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.  The letter indicates that General Drakkisath guards the brand. Perhaps you should investigate.", xp={60,6600}},
  [7877]={n="The Treasure of the Shen'dralar", l=60, r=56, g={"Shen'dralar Ancient"}, t={"Treasure of the Shen'dralar"}, ot="Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!", sh=true, ps={7461}, xp={60,660}},
